function seatFamilies(n: number, reserved: number[][]): number {
  const rows = new Map<number, Set<number>>();
  for (const [r, s] of reserved) {
    if (!rows.has(r)) rows.set(r, new Set());
    rows.get(r)!.add(s);
  }
  let total = 2 * (n - rows.size);
  for (const sold of rows.values()) {
    const free = (a: number) => [0, 1, 2, 3].every(d => !sold.has(a + d));
    if (free(2) && free(6)) total += 2;
    else if (free(2) || free(4) || free(6)) total += 1;
  }
  return total;
}

