    def seatFamilies(self, n: int, reserved: List[List[int]]) -> int:
        rows = defaultdict(set)
        for r, s in reserved:
            rows[r].add(s)
        total = 2 * (n - len(rows))
        for sold in rows.values():
            def free(a):
                return all(a + d not in sold for d in range(4))
            if free(2) and free(6):
                total += 2
            elif free(2) or free(4) or free(6):
                total += 1
        return total

