function seatFamilies(n: number, reserved: number[][]): number {
  const LEFT = 0b111100, MID = 0b11110000, RIGHT = 0b1111000000; // seats 2-5, 4-7, 6-9
  const rows = new Map<number, number>();
  for (const [r, s] of reserved) rows.set(r, (rows.get(r) ?? 0) | (1 << s));
  let total = 2 * (n - rows.size);
  for (const mask of rows.values()) {
    const l = (mask & LEFT) === 0, m = (mask & MID) === 0, rt = (mask & RIGHT) === 0;
    if (l && rt) total += 2;
    else if (l || m || rt) total += 1;
  }
  return total;
}

